// ─── KPI Card ─────────────────────────────────────────────────────────────────
function KpiCard({
  title, value, rawValue, sub, icon, gradient, accent, border, trend
}: {
  title: string;
  value?: number;
  rawValue?: string;
  sub: string;
  icon: React.ReactNode;
  gradient: string;
  accent: string;
  border: string;
  trend?: "up" | "down";
}) {
  const numericTarget = typeof value === "number" ? value : 0;
  const counted = useCountUp(numericTarget, 1400);
  const displayValue = rawValue ?? (typeof value === "number" ? counted.toLocaleString() : (value || "0"));

  return (
    <motion.div
      variants={cardVariants}
      whileHover={{ y: -4, scale: 1.015, transition: { type: "spring" as const, stiffness: 400, damping: 20 } }}
      className={`relative bg-gradient-to-br ${gradient} border ${border} rounded-2xl p-5 flex flex-col justify-between shadow-sm overflow-hidden cursor-default`}
    >
      {/* BG glow */}
      <div className={`absolute inset-0 bg-gradient-to-br ${gradient} opacity-40 pointer-events-none`} />

      <div className="flex justify-between items-start mb-4 relative">
        <h3 className="text-muted font-medium text-xs uppercase tracking-wider">{title}</h3>
        <div className={`p-2 bg-black/20 backdrop-blur-sm rounded-xl border border-white/5 ${accent}`}>
          {icon}
        </div>
      </div>

      <div className="relative">
        <div className="text-3xl font-bold tracking-tight text-main mb-1 font-mono">
          {displayValue}
        </div>
        <div className="flex items-center gap-1.5">
          {trend && (
            <span className={trend === "up" ? "text-emerald-400" : "text-red-400"}>
              {trend === "up"
                ? <ArrowUpRight size={12} />
                : <ArrowDownRight size={12} />}
            </span>
          )}
          <div className="text-xs text-muted">{sub}</div>
        </div>
      </div>
    </motion.div>
  );
}

// ─── Usage Card (animated bar) ────────────────────────────────────────────────
function UsageCard({ label, value, max, icon, color }: {
  label: string;
  value: number;
  max: number;
  icon: React.ReactNode;
  color: string;
}) {
  const safeValue = value || 0;
  const percent = Math.min(100, Math.max(0, (safeValue / max) * 100));
  const counted = useCountUp(safeValue, 1000);

  return (
    <motion.div
      variants={cardVariants}
      whileHover={{ y: -3, scale: 1.01, transition: { type: "spring" as const, stiffness: 400, damping: 20 } }}
      className="bg-card border border-subtle rounded-2xl p-4 shadow-sm"
    >
      <div className="flex justify-between items-center mb-3">
        <div className="flex items-center gap-2 text-secondary text-xs font-medium">
          <span style={{ color }}>{icon}</span>
          {label}
        </div>
        <span className="text-muted font-mono text-xs font-medium">{counted} / {max}</span>
      </div>
      <div className="w-full bg-input border border-subtle rounded-full h-2 overflow-hidden">
        <motion.div
          initial={{ width: 0 }}
          animate={{ width: `${percent}%` }}
          transition={{ duration: 1.2, ease: "easeOut" as const, delay: 0.2 }}
          className="h-full rounded-full"
          style={{ backgroundColor: color }}
        />
      </div>
      <div className="mt-2 text-right">
        <span
          className="text-[10px] font-bold font-mono"
          style={{ color }}
        >
          {percent.toFixed(0)}%
        </span>
      </div>
    </motion.div>
  );
}

// ─── Donut Chart (SVG) ────────────────────────────────────────────────────────
function UsageDonut({ searches, splits, pnr, tracking }: {
  searches: number;
  splits: number;
  pnr: number;
  tracking: number;
}) {
  const total = searches + splits + pnr + tracking || 1;
  const slices = [
    { label: "Searches", value: searches, color: "#6366f1" },
    { label: "Splits", value: splits, color: "#8b5cf6" },
    { label: "PNR", value: pnr, color: "#06b6d4" },
    { label: "Tracking", value: tracking, color: "#10b981" },
  ];

  const r = 52;
  const cx = 70;
  const cy = 70;
  const circumference = 2 * Math.PI * r;

  let accumulated = 0;

  return (
    <motion.div
      variants={cardVariants}
      whileHover={{ y: -3, transition: { type: "spring" as const, stiffness: 400, damping: 20 } }}
      className="bg-card border border-subtle rounded-2xl p-5 shadow-sm flex flex-col justify-between"
    >
      <div className="flex items-center gap-2 mb-4">
        <PieChart size={16} className="text-indigo-400" />
        <h3 className="text-xs font-bold text-secondary uppercase tracking-wider">API Usage Mix</h3>
      </div>

      <div className="flex items-center gap-4 justify-center">
        <div className="relative shrink-0">
          <svg viewBox="0 0 140 140" className="w-28 h-28 -rotate-90">
            {/* Background ring */}
            <circle cx={cx} cy={cy} r={r} fill="none" stroke="currentColor" strokeWidth="14" className="text-input" />
            {slices.map((slice, i) => {
              const slicePercent = slice.value / total;
              const dashLen = circumference * slicePercent;
              const offset = circumference * (1 - accumulated);
              accumulated += slicePercent;

              return (
                <motion.circle
                  key={i}
                  cx={cx}
                  cy={cy}
                  r={r}
                  fill="none"
                  stroke={slice.color}
                  strokeWidth="14"
                  strokeDasharray={`${dashLen} ${circumference - dashLen}`}
                  strokeDashoffset={offset}
                  strokeLinecap="round"
                  initial={{ strokeDasharray: `0 ${circumference}` }}
                  animate={{ strokeDasharray: `${dashLen} ${circumference - dashLen}` }}
                  transition={{ duration: 1.2, delay: 0.1 + i * 0.15, ease: "easeOut" as const }}
                />
              );
            })}
          </svg>
          {/* Center label */}
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-xs font-bold text-main font-mono">{total.toLocaleString()}</span>
            <span className="text-[9px] text-muted">total</span>
          </div>
        </div>

        {/* Legend */}
        <div className="space-y-2 min-w-0">
          {slices.map((s, i) => (
            <div key={i} className="flex items-center gap-2 text-xs">
              <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: s.color }} />
              <span className="text-muted truncate">{s.label}</span>
              <span className="text-main font-mono font-medium ml-auto">{s.value}</span>
            </div>
          ))}
        </div>
      </div>
    </motion.div>
  );
}

