// ─── LogsExporter Component ──────────────────────────────────────────────────
function LogsExporter({
  api,
  getAuthHeaders,
  triggerToast
}: {
  api: string;
  getAuthHeaders?: () => any;
  triggerToast?: (msg: string, type: "success" | "error" | "info") => void;
}) {
  const [startDate, setStartDate] = useState<string>(() => {
    const d = new Date();
    d.setDate(d.getDate() - 7);
    return d.toISOString().split("T")[0];
  });
  const [endDate, setEndDate] = useState<string>(() => {
    return new Date().toISOString().split("T")[0];
  });
  const [exporting, setExporting] = useState<boolean>(false);

  const handleExport = async () => {
    try {
      setExporting(true);
      if (triggerToast) triggerToast("Generating CSV telemetry report...", "info");

      const headers = getAuthHeaders ? getAuthHeaders() : {};
      const res = await fetchWithAuth(`${api}/api/admin/analytics/export?startDate=${startDate}&endDate=${endDate}`, {
        headers
      });

      if (!res.ok) {
        throw new Error(`HTTP status ${res.status}`);
      }

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `telemetry_logs_${startDate}_to_${endDate}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      if (triggerToast) triggerToast("CSV logs successfully downloaded!", "success");
    } catch (err: any) {
      console.error(err);
      if (triggerToast) triggerToast(`Export failed: ${err.message}`, "error");
    } finally {
      setExporting(false);
    }
  };

  return (
    <motion.div
      variants={cardVariants}
      whileHover={{ y: -3, transition: { type: "spring" as const, stiffness: 400, damping: 20 } }}
      className="bg-card border border-subtle rounded-2xl p-5 shadow-sm h-full"
    >
      <h3 className="text-main font-semibold mb-1 flex items-center gap-2 text-sm">
        <Activity size={16} className="text-indigo-400" /> Log Telemetry Exporter
      </h3>
      <p className="text-xs text-muted mb-4 leading-relaxed">
        Export raw telemetry events and system metrics to standard RFC 4180 CSV files. Max range cap of 31 days is automatically enforced.
      </p>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
        <div>
          <label className="block text-[10px] uppercase font-bold tracking-wider text-muted mb-1.5">Start Date</label>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="w-full bg-input border border-subtle hover:border-strong rounded-lg px-3 py-2 text-xs font-mono text-main outline-none focus:border-indigo-500 transition"
          />
        </div>
        <div>
          <label className="block text-[10px] uppercase font-bold tracking-wider text-muted mb-1.5">End Date</label>
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="w-full bg-input border border-subtle hover:border-strong rounded-lg px-3 py-2 text-xs font-mono text-main outline-none focus:border-indigo-500 transition"
          />
        </div>
      </div>
      <button
        onClick={handleExport}
        disabled={exporting}
        className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-input disabled:text-muted border border-indigo-550/20 rounded-xl text-xs font-bold transition flex items-center justify-center gap-2 text-white shadow-[0_4px_12px_rgba(79,70,229,0.2)]"
      >
        {exporting ? (
          <>
            <RefreshCw size={14} className="animate-spin" /> Exporting Logs...
          </>
        ) : (
          <>
            <BarChart3 size={14} /> Download CSV Telemetry Logs
          </>
        )}
      </button>
    </motion.div>
  );
}

