// ─── Types ────────────────────────────────────────────────────────────────────
interface NewsKpis {
  drafts: number;
  review_queue: number;
  approved: number;
  scheduled: number;
  published: number;
  rejected: number;
  archived: number;
  unpublished: number;
}

interface NewsArticle {
  id: string;
  title: string;
  source_name: string;
  source_url: string;
  source_tier: string;
  category: string;
  status: string;
  relevance_score: number;
  ai_confidence: string | null;
  rejection_reason: string | null;
  affected_trains: string[];
  affected_stations: string[];
  published_at: string;
  updated_at: string;
  scheduled_at: string | null;
}

interface NewsControlCenterPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

