// ─── Component ────────────────────────────────────────────────────────────────
export function NewsControlCenterPanel({ api, getAuthHeaders, triggerToast }: NewsControlCenterPanelProps) {
  const [articles, setArticles] = useState<NewsArticle[]>([]);
  const [kpis, setKpis] = useState<NewsKpis>({ drafts: 0, review_queue: 0, approved: 0, scheduled: 0, published: 0, rejected: 0, archived: 0, unpublished: 0 });
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  // Auto-Curator state (Phase 087 Autonomous SEO Publisher)
  const [autoCuratorEnabled, setAutoCuratorEnabled] = useState(true);
  const [publishedToday, setPublishedToday] = useState(0);
  const [curatingNow, setCuratingNow] = useState(false);
  const [cleaningNow, setCleaningNow] = useState(false);

  // Guide modal / accordion state
  const [showGuide, setShowGuide] = useState(false);
  const [guideTab, setGuideTab] = useState<"how-it-works" | "quality-policy" | "seo-policy">("how-it-works");

  // Train Guide Generator state (Phase 1 Programmatic SEO)
  const [showGuideModal, setShowGuideModal] = useState(false);
  const [trainGuideNumber, setTrainGuideNumber] = useState("");
  const [trainGuideLang, setTrainGuideLang] = useState<"en" | "hi">("en");
  const [trainGuideKeywords, setTrainGuideKeywords] = useState("");
  const [trainGuideEnableWebSearch, setTrainGuideEnableWebSearch] = useState(true);
  const [trainGuideTopics, setTrainGuideTopics] = useState<string[]>([
    "history", "timetable", "tourism", "coaches", "fare_tatkal", "cancellation_refund", "flight_vs_train", "food_pantry", "travel_tips", "split_journey"
  ]);
  const [trainGuideAutoPublish, setTrainGuideAutoPublish] = useState(true);
  const [generatingGuide, setGeneratingGuide] = useState(false);
  const [generatedResult, setGeneratedResult] = useState<any>(null);

  const toggleTopic = (topicId: string) => {
    setTrainGuideTopics((prev) => {
      if (prev.includes(topicId)) {
        if (prev.length === 1) return prev;
        return prev.filter((id) => id !== topicId);
      } else {
        return [...prev, topicId];
      }
    });
  };

  const selectAllTopics = () => {
    setTrainGuideTopics(GUIDE_TOPIC_OPTIONS.map((t) => t.id));
  };

  const selectSingleTopic = (topicId: string) => {
    setTrainGuideTopics([topicId]);
  };

  // Filters
  const [statusFilter, setStatusFilter] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [tierFilter, setTierFilter] = useState("");
  const [searchFilter, setSearchFilter] = useState("");
  const [limit] = useState(50);
  const [offset, setOffset] = useState(0);

  const fetchArticles = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set("status", statusFilter);
      if (categoryFilter) params.set("category", categoryFilter);
      if (tierFilter) params.set("sourceTier", tierFilter);
      if (searchFilter) params.set("search", searchFilter);
      params.set("limit", String(limit));
      params.set("offset", String(offset));

      const res = await fetchWithAuth(`${api}/api/admin/news?${params}`, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success) {
        setArticles(json.articles || []);
        setTotal(json.total || 0);
        setKpis(json.kpis || {});
      } else {
        triggerToast(json.error || "Failed to load news articles", "error");
      }
    } catch {
      triggerToast("Network error loading news", "error");
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders, statusFilter, categoryFilter, tierFilter, searchFilter, limit, offset]);

  useEffect(() => { fetchArticles(); }, [fetchArticles]);

  const fetchCuratorStatus = useCallback(async () => {
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/autocurator/status`, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success && json.data) {
        setAutoCuratorEnabled(json.data.config?.enabled ?? true);
        setPublishedToday(json.data.publishedToday || 0);
      }
    } catch {
      // Non-fatal
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchCuratorStatus();
  }, [fetchCuratorStatus]);

  const handleToggleAutoCurator = async () => {
    const nextState = !autoCuratorEnabled;
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/autocurator/toggle`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ enabled: nextState }),
      });
      const json = await res.json();
      if (json.success) {
        setAutoCuratorEnabled(nextState);
        triggerToast(`Auto-Curator ${nextState ? "ACTIVATED (Max 5/day)" : "PAUSED"} ✓`, "success");
      }
    } catch {
      triggerToast("Failed to toggle auto-curator", "error");
    }
  };

  const handleRunAutoCuratorNow = async () => {
    setCuratingNow(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/autocurator/run`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ maxArticles: 5 }),
      });
      const json = await res.json();
      if (json.success) {
        const count = json.data?.publishedCount || 0;
        triggerToast(`Auto-Curated & Published ${count} passenger articles ✓`, "success");
        fetchArticles();
        fetchCuratorStatus();
      } else {
        triggerToast(json.error || "Auto-curation failed", "error");
      }
    } catch {
      triggerToast("Network error during auto-curation", "error");
    } finally {
      setCuratingNow(false);
    }
  };

  const handleCleanStaleDrafts = async () => {
    if (!window.confirm("Are you sure you want to archive drafts older than 7 days? This will clean up your backlog.")) {
      return;
    }
    setCleaningNow(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/autocurator/cleanup`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ olderThanDays: 7 }),
      });
      const json = await res.json();
      if (json.success) {
        triggerToast(`Archived ${json.archivedCount} stale drafts ✓ Backlog Cleaned!`, "success");
        fetchArticles();
        fetchCuratorStatus();
      } else {
        triggerToast(json.error || "Cleanup failed", "error");
      }
    } catch {
      triggerToast("Network error during cleanup", "error");
    } finally {
      setCleaningNow(false);
    }
  };

  const handleGenerateTrainGuide = async () => {
    const cleanNo = trainGuideNumber.trim();
    if (cleanNo && !/^\d{5}$/.test(cleanNo)) {
      triggerToast("Please enter a valid 5-digit train number (e.g. 22221) or leave blank if focusing on custom keywords", "error");
      return;
    }
    if (!cleanNo && !trainGuideKeywords.trim()) {
      triggerToast("Please enter either a 5-digit train number or custom keywords", "error");
      return;
    }
    if (trainGuideTopics.length === 0) {
      triggerToast("Please select at least one editorial topic to generate", "error");
      return;
    }
    setGeneratingGuide(true);
    setGeneratedResult(null);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/train-guide/generate`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({
          trainNo: cleanNo || "22221",
          language: trainGuideLang,
          focusTopics: trainGuideTopics,
          focusAngle: trainGuideTopics.join(", "),
          customKeywords: trainGuideKeywords.trim() || undefined,
          enableWebSearch: trainGuideEnableWebSearch,
          autoPublish: trainGuideAutoPublish,
        }),
      });
      const json = await res.json();
      if (json.success) {
        setGeneratedResult(json);
        triggerToast(`Article generated successfully with Web Grounding! ✓`, "success");
        fetchArticles();
      } else {
        triggerToast(json.error || "Failed to generate article", "error");
      }
    } catch {
      triggerToast("Network error generating article", "error");
    } finally {
      setGeneratingGuide(false);
    }
  };

  const quickApprove = async (article: NewsArticle) => {
    if (article.status !== "REVIEW_REQUIRED") {
      triggerToast("Only REVIEW_REQUIRED articles can be approved from the list. Open the review screen.", "info");
      return;
    }
    setActionLoading(article.id);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/${article.id}/approve`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ attestation: "I verified the source and approve this article." }),
      });
      const json = await res.json();
      if (json.success) {
        triggerToast("Article approved ✓", "success");
        fetchArticles();
      } else {
        triggerToast(json.error || "Approval failed", "error");
      }
    } catch {
      triggerToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const quickReject = async (article: NewsArticle) => {
    setActionLoading(article.id);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/${article.id}/reject`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ reason: "OTHER", note: "Quick rejected from list view" }),
      });
      const json = await res.json();
      if (json.success) {
        triggerToast("Article rejected", "success");
        fetchArticles();
      } else {
        triggerToast(json.error || "Reject failed", "error");
      }
    } catch {
      triggerToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const quickPublish = async (article: NewsArticle) => {
    setActionLoading(article.id);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/${article.id}/publish`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
      });
      const json = await res.json();
      if (json.success) {
        triggerToast("Article published live to website ✓", "success");
        fetchArticles();
      } else {
        triggerToast(json.error || "Publish failed", "error");
      }
    } catch {
      triggerToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const quickRestore = async (article: NewsArticle) => {
    setActionLoading(article.id);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/news/${article.id}/restore`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
      });
      const json = await res.json();
      if (json.success) {
        triggerToast("Article restored to draft ✓", "success");
        fetchArticles();
      } else {
        triggerToast(json.error || "Restore failed", "error");
      }
    } catch {
      triggerToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const totalPages = Math.ceil(total / limit);
  const currentPage = Math.floor(offset / limit) + 1;

  return (
    <div className="space-y-6 pb-12">
      {/* Header with Operating Guide Toggle */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-indigo-500/10 border border-indigo-500/20">
            <Newspaper className="text-indigo-400" size={22} />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-black text-main">News Control Center</h2>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-500/15 text-indigo-400 border border-indigo-500/30">
                HUMAN REVIEW GATE
              </span>
            </div>
            <p className="text-xs text-muted mt-0.5">
              Verified railway bulletins, AI draft moderation, SEO metadata verification, and multi-tier source management.
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2.5">
          <button
            id="news-train-guide-btn"
            onClick={() => {
              setGeneratedResult(null);
              setShowGuideModal(true);
            }}
            className="flex items-center gap-1.5 px-3.5 py-2 text-xs font-bold rounded-xl bg-purple-600 hover:bg-purple-700 text-white shadow-md transition-all active:scale-95"
          >
            <Train size={14} />
            <span>🚆 AI Train Guide Generator</span>
          </button>

          <button
            id="news-guide-toggle-btn"
            onClick={() => setShowGuide(!showGuide)}
            className={`flex items-center gap-1.5 px-3.5 py-2 text-xs font-bold rounded-xl border transition-all ${
              showGuide
                ? "bg-indigo-600 text-white border-indigo-500 shadow-md"
                : "bg-input hover:bg-card border-subtle text-main"
            }`}
          >
            <BookOpen size={13} />
            <span>{showGuide ? "Hide CMS Guide" : "📖 How News Works / Admin Guide"}</span>
          </button>

          <button
            id="news-refresh-btn"
            onClick={fetchArticles}
            disabled={loading}
            className="flex items-center gap-2 px-3.5 py-2 text-xs font-bold bg-input hover:bg-card border border-subtle text-main rounded-xl transition"
          >
            <RefreshCw size={12} className={loading ? "animate-spin text-primary" : ""} /> Refresh
          </button>
        </div>
      </div>

      {/* ── PHASE 087 AUTONOMOUS SEO PUBLISHER (ADSENSE-SAFE) CONTROL STRIP ── */}
      <div className="bg-card/70 border border-subtle rounded-2xl p-4 sm:p-5 shadow-sm backdrop-blur-sm flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <div className="flex items-center gap-3.5">
          <div className={`p-3 rounded-xl border shrink-0 ${
            autoCuratorEnabled
              ? "bg-emerald-500/10 border-emerald-500/25 text-emerald-400"
              : "bg-slate-500/10 border-slate-500/25 text-slate-400"
          }`}>
            <Sparkles size={20} />
          </div>
          <div>
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-sm font-bold text-main">Autonomous SEO Publisher</span>
              <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border flex items-center gap-1 ${
                autoCuratorEnabled
                  ? "bg-emerald-500/15 text-emerald-400 border-emerald-500/30"
                  : "bg-amber-500/15 text-amber-400 border-amber-500/30"
              }`}>
                <span className={`w-1.5 h-1.5 rounded-full ${autoCuratorEnabled ? "bg-emerald-400 animate-pulse" : "bg-amber-400"}`} />
                {autoCuratorEnabled ? `ACTIVE (Today: ${publishedToday}/5)` : "PAUSED"}
              </span>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-blue-500/10 text-blue-400 border border-blue-500/20">
                Google AdSense Safe
              </span>
            </div>
            <p className="text-xs text-muted mt-1">
              Auto-filters passenger utility news, enriches Schema.org FAQs &amp; advice, caps at 5/day to prevent spam, and publishes 24/7.
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2.5 shrink-0">
          <button
            onClick={handleToggleAutoCurator}
            className={`flex items-center gap-1.5 px-3 py-2 text-xs font-bold rounded-xl border transition ${
              autoCuratorEnabled
                ? "bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border-emerald-500/30"
                : "bg-input hover:bg-card text-muted border-subtle"
            }`}
            title="Toggle autonomous background publishing"
          >
            <Power size={13} />
            <span>{autoCuratorEnabled ? "Auto-Publish: ON" : "Auto-Publish: OFF"}</span>
          </button>

          <button
            onClick={handleRunAutoCuratorNow}
            disabled={curatingNow}
            className="flex items-center gap-1.5 px-3.5 py-2 text-xs font-bold bg-primary hover:bg-primary/90 text-white rounded-xl shadow-sm transition disabled:opacity-50"
            title="Scan drafts, filter noise, and publish top passenger articles now"
          >
            {curatingNow ? <Loader2 size={13} className="animate-spin" /> : <Zap size={13} />}
            <span>{curatingNow ? "Curating..." : "⚡ Auto-Curate & Publish Now"}</span>
          </button>

          <button
            onClick={handleCleanStaleDrafts}
            disabled={cleaningNow}
            className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-input hover:bg-red-500/10 text-muted hover:text-red-400 border border-subtle hover:border-red-500/20 rounded-xl transition disabled:opacity-50"
            title="Archive drafts older than 7 days to clean up backlog"
          >
            {cleaningNow ? <Loader2 size={13} className="animate-spin" /> : <Trash2 size={13} />}
            <span>{cleaningNow ? "Cleaning..." : "🧹 Clean Stale Backlog"}</span>
          </button>
        </div>
      </div>

      {/* ── EXPANDABLE ADMIN OPERATING GUIDE & QUALITY POLICY ─────────── */}
      {showGuide && (
        <div className="bg-card border border-indigo-500/30 rounded-2xl p-6 shadow-xl space-y-5 animate-in fade-in slide-in-from-top-2 duration-200">
          {/* Guide Sub-tabs */}
          <div className="flex flex-wrap items-center justify-between gap-3 border-b border-subtle pb-4">
            <div className="flex items-center gap-2">
              <Sparkles className="text-indigo-400" size={18} />
              <h3 className="font-extrabold text-sm text-main">Trayago News CMS — Operational Knowledge &amp; Policies</h3>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {[
                { id: "how-it-works", label: "1. How News Works (10 Rules)", icon: Info },
                { id: "quality-policy", label: "2. Railway Quality Policy", icon: Shield },
                { id: "seo-policy", label: "3. SEO Content Guidelines", icon: Globe },
              ].map(tab => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setGuideTab(tab.id as any)}
                    className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                      guideTab === tab.id
                        ? "bg-indigo-500 text-white shadow-sm"
                        : "bg-input border border-subtle text-muted hover:text-main"
                    }`}
                  >
                    <Icon size={12} />
                    {tab.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* TAB 1: 10-Point How News Works */}
          {guideTab === "how-it-works" && (
            <div className="space-y-4">
              <div className="p-3 bg-indigo-500/5 border border-indigo-500/20 rounded-xl text-xs text-muted leading-relaxed">
                <strong className="text-indigo-400">Non-Technical Admin Overview:</strong> Trayago News is designed so any team member can operate the editorial desk without developer assistance. Read these 10 core principles to manage articles safely.
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5 text-xs">
                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">1</span>
                    Where News comes from
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    Automated ingestors scrape verified feeds: <strong>Tier-1</strong> (IRCTC, Railway Board), <strong>Tier-2</strong> (PIB, Zonal Divisions), and <strong>Tier-3</strong> (Recognized media like NDTV, TOI, Mint).
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">2</span>
                    What AI does
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    AI strips HTML, deduplicates via SimHash fingerprints, extracts train numbers &amp; stations, scores relevance ($0-100$), and prepares draft summaries with bullet takeaways.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">3</span>
                    What Admin must verify
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    Always open the <strong>Original Source link</strong>. Confirm train numbers, dates, stations, and facts. Ensure AI has not generated hallucinated or speculative claims.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">4</span>
                    How to approve an article
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    Click <strong>Review</strong> on any <em>REVIEW_REQUIRED</em> item. Complete the 4-point pre-approval checklist and click <strong>Confirm Approval</strong>.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">5</span>
                    How to reject an article
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    If an article is off-topic, duplicate, outdated, or factually flawed, click <strong>Reject</strong>, select the reason (e.g. <em>UNSUPPORTED_CLAIM</em>), and save.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">6</span>
                    How to schedule publishing
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    For future announcements or embargoed press releases, approve first, then click <strong>Schedule</strong> and pick a future release timestamp.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">7</span>
                    How to publish live
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    Click <strong>Publish</strong> once approved. The article goes live on <code>/news</code> immediately and is automatically registered in <code>/sitemap.xml</code>.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">8</span>
                    How SEO fields work
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    <strong>SEO Title</strong> = Google headline. <strong>Meta Description</strong> = snippet text under title. <strong>Slug</strong> = clean web address. JSON-LD structured schemas are automatic!
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-main flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-[10px] font-mono">9</span>
                    How to update an old article
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    Open the article in review view, update text or takeaways, and click <strong>Save Draft</strong>. The live page updates upon save.
                  </p>
                </div>

                <div className="p-3.5 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="font-bold text-red-400 flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-mono">10</span>
                    What NOT to do
                  </div>
                  <p className="text-muted text-[11px] leading-relaxed">
                    <strong>NEVER</strong> attempt to publish raw AI drafts without review. <strong>NEVER</strong> delete source links. <strong>NEVER</strong> keyword-stuff station names artificially.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* TAB 2: Railway Quality Policy */}
          {guideTab === "quality-policy" && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
                {/* Allowed Topics */}
                <div className="p-4 bg-emerald-500/5 border border-emerald-500/20 rounded-xl space-y-2.5">
                  <div className="font-black text-emerald-400 flex items-center gap-2 text-sm">
                    <CheckCircle2 size={16} />
                    <span>ALLOWED TOPICS (Strict Railway Focus)</span>
                  </div>
                  <ul className="space-y-1.5 text-muted text-[11px] list-disc list-inside">
                    <li><strong className="text-main">Train Cancellations &amp; Diversions:</strong> Route blocks, safety mega blocks, fog delays.</li>
                    <li><strong className="text-main">Timetable &amp; Route Changes:</strong> New station halts, changed departure timings.</li>
                    <li><strong className="text-main">New &amp; Special Trains:</strong> Vande Bharat, Amrit Bharat, festival &amp; holiday specials.</li>
                    <li><strong className="text-main">Station Updates:</strong> Amrit Bharat Station Scheme, platform changes, amenities.</li>
                    <li><strong className="text-main">IRCTC &amp; Tatkal Rules:</strong> Booking timings, OTP changes, chart preparation rules.</li>
                    <li><strong className="text-main">Refund &amp; Cancellation:</strong> TDR filing guidelines, refund eligibility rules.</li>
                    <li><strong className="text-main">PNR &amp; RAC/WL Guidance:</strong> Confirmation logic, berth allocation advisories.</li>
                    <li><strong className="text-main">Passenger Travel Advisories:</strong> Luggage rules, safety advisories, medical help.</li>
                  </ul>
                </div>

                {/* Topics to Avoid */}
                <div className="p-4 bg-red-500/5 border border-red-500/20 rounded-xl space-y-2.5">
                  <div className="font-black text-red-400 flex items-center gap-2 text-sm">
                    <XCircle size={16} />
                    <span>TOPICS TO AVOID (Strict Rejection Policy)</span>
                  </div>
                  <ul className="space-y-1.5 text-muted text-[11px] list-disc list-inside">
                    <li><strong className="text-main">Generic Politics:</strong> Partisan debates, political rallies, elections unrelated to transit.</li>
                    <li><strong className="text-main">Entertainment / Gossip:</strong> Celebrity travel gossip, film shoots on trains.</li>
                    <li><strong className="text-main">Generic Corporate Finance:</strong> Stock market tips, unrelated company balance sheets.</li>
                    <li><strong className="text-main">Unrelated Breaking News:</strong> General accidents, local crimes unrelated to rail ops.</li>
                    <li><strong className="text-main">Keyword-Stuffed Content:</strong> Repetitive lists of train names without real news.</li>
                    <li><strong className="text-main">AI Hallucinations:</strong> Invented train schedules without official press verification.</li>
                    <li><strong className="text-main">Duplicates:</strong> Same press release reprinted across multiple media portals.</li>
                  </ul>
                </div>
              </div>
            </div>
          )}

          {/* TAB 3: SEO Content Guidelines */}
          {guideTab === "seo-policy" && (
            <div className="p-4 bg-input border border-subtle rounded-xl space-y-3 text-xs">
              <div className="font-bold text-main flex items-center gap-2 text-sm">
                <Globe className="text-emerald-400" size={16} />
                <span>Passenger-First SEO Doctrine (Google Helpful Content Compliant)</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3 text-[11px] text-muted">
                <div className="p-3 bg-card border border-subtle rounded-lg space-y-1">
                  <div className="font-bold text-main">1. Answer Questions First</div>
                  <p>Passengers want to know: <em>Is my train delayed? What is the refund rule? Which train is running?</em> Put answers in the first 2 sentences.</p>
                </div>
                <div className="p-3 bg-card border border-subtle rounded-lg space-y-1">
                  <div className="font-bold text-main">2. Zero Keyword Stuffing</div>
                  <p>Never repeat "tatkal booking irctc online" 20 times. Write naturally in clear English/Hindi with proper punctuation.</p>
                </div>
                <div className="p-3 bg-card border border-subtle rounded-lg space-y-1">
                  <div className="font-bold text-main">3. Immutable Attribution</div>
                  <p>Always preserve the verified source URL and publisher name. High-trust citations build long-term domain authority.</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* KPI Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-3">
        {[
          { label: "Drafts",       value: kpis.drafts,       color: "text-indigo-400",  filter: "AI_DRAFTED",      icon: <Circle size={14} /> },
          { label: "Review Queue", value: kpis.review_queue, color: "text-orange-400",  filter: "REVIEW_REQUIRED", icon: <AlertTriangle size={14} /> },
          { label: "Approved",     value: kpis.approved,     color: "text-emerald-400", filter: "APPROVED",        icon: <CheckCircle size={14} /> },
          { label: "Scheduled",    value: kpis.scheduled,    color: "text-cyan-400",    filter: "SCHEDULED",       icon: <Calendar size={14} /> },
          { label: "Published",    value: kpis.published,    color: "text-green-400",   filter: "PUBLISHED",       icon: <ShieldCheck size={14} /> },
          { label: "Unpublished",  value: kpis.unpublished,  color: "text-yellow-400",  filter: "UNPUBLISHED",     icon: <Eye size={14} /> },
          { label: "Rejected",     value: kpis.rejected,     color: "text-red-400",     filter: "REJECTED",        icon: <XCircle size={14} /> },
          { label: "Archived",     value: kpis.archived,     color: "text-slate-400",   filter: "ARCHIVED",        icon: <Archive size={14} /> },
        ].map(kpi => (
          <button
            key={kpi.label}
            id={`news-kpi-${kpi.filter.toLowerCase()}`}
            onClick={() => { setStatusFilter(statusFilter === kpi.filter ? "" : kpi.filter); setOffset(0); }}
            className={`bg-card border rounded-xl p-4 flex flex-col gap-1 text-left transition hover:border-indigo-500/50 ${
              statusFilter === kpi.filter ? "border-indigo-500/60 shadow-lg shadow-indigo-500/10" : "border-subtle"
            }`}
          >
            <div className={`flex items-center gap-1.5 ${kpi.color} text-xs font-semibold`}>
              {kpi.icon} {kpi.label}
            </div>
            <div className={`text-2xl font-black ${kpi.color}`}>{kpi.value}</div>
          </button>
        ))}
      </div>

      {/* Filters */}
      <div className="bg-card border border-subtle rounded-xl p-4 flex flex-wrap gap-3 items-center">
        <div className="flex items-center gap-2 flex-1 min-w-[200px] bg-input border border-subtle rounded-lg px-3 py-2">
          <Search size={13} className="text-muted shrink-0" />
          <input
            id="news-search"
            value={searchFilter}
            onChange={e => { setSearchFilter(e.target.value); setOffset(0); }}
            placeholder="Search headlines..."
            className="bg-transparent text-xs text-main placeholder:text-muted outline-none w-full"
          />
        </div>

        <select
          id="news-filter-status"
          value={statusFilter}
          onChange={e => { setStatusFilter(e.target.value); setOffset(0); }}
          className="bg-input border border-subtle text-xs text-main rounded-lg px-3 py-2 outline-none"
        >
          <option value="">All Statuses</option>
          {Object.entries(STATUS_CONFIG).map(([key, cfg]) => (
            <option key={key} value={key}>{cfg.label}</option>
          ))}
        </select>

        <select
          id="news-filter-category"
          value={categoryFilter}
          onChange={e => { setCategoryFilter(e.target.value); setOffset(0); }}
          className="bg-input border border-subtle text-xs text-main rounded-lg px-3 py-2 outline-none"
        >
          <option value="">All Categories</option>
          {["Special Trains", "Delays", "Cancellation", "Safety", "Operations", "Infrastructure", "Policy", "Railway Updates"].map(c => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>

        <select
          id="news-filter-tier"
          value={tierFilter}
          onChange={e => { setTierFilter(e.target.value); setOffset(0); }}
          className="bg-input border border-subtle text-xs text-main rounded-lg px-3 py-2 outline-none"
        >
          <option value="">All Source Tiers</option>
          <option value="TIER_1_OFFICIAL">T1 Official</option>
          <option value="TIER_2_GOVERNMENT">T2 Government</option>
          <option value="TIER_3_RECOGNIZED_MEDIA">T3 Media</option>
        </select>

        {(statusFilter || categoryFilter || tierFilter || searchFilter) && (
          <button
            id="news-clear-filters"
            onClick={() => { setStatusFilter(""); setCategoryFilter(""); setTierFilter(""); setSearchFilter(""); setOffset(0); }}
            className="text-xs text-muted hover:text-danger flex items-center gap-1 transition"
          >
            <XCircle size={13} /> Clear
          </button>
        )}

        <div className="ml-auto text-xs text-muted font-medium">
          {total} article{total !== 1 ? "s" : ""}
        </div>
      </div>

      {/* Article Table */}
      <div className="bg-card border border-subtle rounded-xl overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="animate-spin text-primary" size={28} />
          </div>
        ) : articles.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-muted gap-3">
            <Newspaper size={36} className="opacity-30" />
            <p className="text-sm">No articles match the current filters.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-subtle bg-input">
                  {["Headline", "Source", "Tier", "Category", "Confidence", "Status", "Updated", "Actions"].map(h => (
                    <th key={h} className="text-left px-4 py-3 text-muted font-semibold uppercase tracking-wider whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-subtle">
                {articles.map(article => {
                  const statusCfg = STATUS_CONFIG[article.status] || { label: article.status, color: "text-muted", bg: "bg-muted/10" };
                  const tierCfg = TIER_BADGE[article.source_tier] || { label: article.source_tier, color: "text-muted" };
                  const isActioning = actionLoading === article.id;

                  return (
                    <tr key={article.id} className="hover:bg-input/50 transition-colors group">
                      {/* Headline */}
                      <td className="px-4 py-3 max-w-[280px]">
                        <div className="font-semibold text-main line-clamp-2 leading-tight" title={article.title}>
                          {article.title}
                        </div>
                        {article.affected_trains?.length > 0 && (
                          <div className="text-muted text-[10px] mt-1 truncate">
                            🚂 {article.affected_trains.slice(0, 3).join(", ")}
                          </div>
                        )}
                      </td>

                      {/* Source */}
                      <td className="px-4 py-3 max-w-[140px]">
                        <div className="flex items-center gap-1.5">
                          <span className="text-secondary truncate font-medium">{article.source_name}</span>
                          <a
                            href={article.source_url}
                            target="_blank"
                            rel="noopener noreferrer"
                            id={`news-src-link-${article.id}`}
                            className="text-muted hover:text-primary transition shrink-0"
                            title="Open source URL"
                          >
                            <ExternalLink size={11} />
                          </a>
                        </div>
                        <div className="text-muted text-[10px] mt-0.5">
                          {new Date(article.published_at).toLocaleDateString("en-IN", { day: "numeric", month: "short" })}
                        </div>
                      </td>

                      {/* Tier */}
                      <td className="px-4 py-3 whitespace-nowrap">
                        <span className={`font-semibold ${tierCfg.color}`}>{tierCfg.label}</span>
                      </td>

                      {/* Category */}
                      <td className="px-4 py-3 whitespace-nowrap">
                        <span className="flex items-center gap-1 text-secondary">
                          <Tag size={11} />
                          {article.category}
                        </span>
                      </td>

                      {/* Confidence */}
                      <td className="px-4 py-3 whitespace-nowrap">
                        {article.ai_confidence ? (
                          <span className={`font-bold ${CONFIDENCE_BADGE[article.ai_confidence] || "text-muted"}`}>
                            {article.ai_confidence}
                          </span>
                        ) : (
                          <span className="text-muted">—</span>
                        )}
                      </td>

                      {/* Status */}
                      <td className="px-4 py-3 whitespace-nowrap">
                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${statusCfg.color} ${statusCfg.bg}`}>
                          {statusCfg.label}
                        </span>
                      </td>

                      {/* Updated */}
                      <td className="px-4 py-3 whitespace-nowrap text-muted">
                        {new Date(article.updated_at).toLocaleDateString("en-IN", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}
                      </td>

                      {/* Actions */}
                      <td className="px-4 py-3 whitespace-nowrap">
                        <div className="flex items-center gap-1.5">
                          <Link
                            id={`news-review-${article.id}`}
                            href={`/admin/news/${article.id}`}
                            className="px-2.5 py-1 bg-indigo-500/10 border border-indigo-500/20 hover:bg-indigo-500/20 text-indigo-400 rounded-lg text-[10px] font-bold transition flex items-center gap-1"
                          >
                            <Eye size={10} /> Review
                          </Link>

                          {["AI_DRAFTED", "REVIEW_REQUIRED"].includes(article.status) && (
                            <button
                              id={`news-approve-quick-${article.id}`}
                              onClick={() => quickApprove(article)}
                              disabled={isActioning}
                              title="Quick approve (attestation pre-checked)"
                              className="px-2 py-1 bg-emerald-500/10 border border-emerald-500/20 hover:bg-emerald-500/20 text-emerald-400 rounded-lg text-[10px] font-bold transition flex items-center gap-1"
                            >
                              {isActioning ? <Loader2 size={10} className="animate-spin" /> : <CheckCircle size={10} />}
                              <span>Approve</span>
                            </button>
                          )}

                          {article.status === "APPROVED" && (
                            <button
                              id={`news-publish-quick-${article.id}`}
                              onClick={() => quickPublish(article)}
                              disabled={isActioning}
                              title="Publish live to portal"
                              className="px-2 py-1 bg-green-500/10 border border-green-500/20 hover:bg-green-500/20 text-green-400 rounded-lg text-[10px] font-bold transition flex items-center gap-1"
                            >
                              {isActioning ? <Loader2 size={10} className="animate-spin" /> : <Globe size={10} />}
                              <span>Publish</span>
                            </button>
                          )}

                          {article.status === "ARCHIVED" && (
                            <button
                              id={`news-restore-quick-${article.id}`}
                              onClick={() => quickRestore(article)}
                              disabled={isActioning}
                              title="Restore to Draft"
                              className="px-2 py-1 bg-indigo-500/10 border border-indigo-500/20 hover:bg-indigo-500/20 text-indigo-400 rounded-lg text-[10px] font-bold transition flex items-center gap-1"
                            >
                              {isActioning ? <Loader2 size={10} className="animate-spin" /> : <RotateCcw size={10} />}
                              <span>Restore</span>
                            </button>
                          )}

                          {["AI_DRAFTED", "REVIEW_REQUIRED", "APPROVED"].includes(article.status) && (
                            <button
                              id={`news-reject-quick-${article.id}`}
                              onClick={() => quickReject(article)}
                              disabled={isActioning}
                              title="Quick reject"
                              className="px-2 py-1 bg-red-500/10 border border-red-500/20 hover:bg-red-500/20 text-red-400 rounded-lg text-[10px] font-bold transition"
                            >
                              {isActioning ? <Loader2 size={10} className="animate-spin" /> : <XCircle size={10} />}
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-3">
          <button
            id="news-prev-page"
            onClick={() => setOffset(Math.max(0, offset - limit))}
            disabled={offset === 0}
            className="px-3 py-1.5 text-xs bg-input border border-subtle rounded-lg text-main disabled:opacity-40 hover:bg-card transition flex items-center gap-1"
          >
            <ChevronLeft size={12} /> Prev
          </button>
          <span className="text-xs text-muted">Page {currentPage} of {totalPages}</span>
          <button
            id="news-next-page"
            onClick={() => setOffset(offset + limit)}
            disabled={currentPage >= totalPages}
            className="px-3 py-1.5 text-xs bg-input border border-subtle rounded-lg text-main disabled:opacity-40 hover:bg-card transition flex items-center gap-1"
          >
            Next <ChevronRight size={12} />
          </button>
        </div>
      )}

      {/* Governance Notice */}
      <div className="flex items-start gap-2.5 p-4 bg-amber-500/5 border border-amber-500/20 rounded-xl text-xs text-amber-400/80">
        <AlertTriangle size={14} className="shrink-0 mt-0.5 text-amber-500" />
        <p>
          <strong className="text-amber-400">Governance:</strong> AI-drafted articles cannot be published directly unless generated via verified Train Guide automation or passed through <strong>REVIEW_REQUIRED → APPROVED</strong> before publishing.
        </p>
      </div>

      {/* ── PROGRAMMATIC SEO TRAIN GUIDE GENERATOR MODAL ── */}
      {showGuideModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-card border border-purple-500/30 rounded-2xl p-6 shadow-2xl max-w-xl w-full space-y-5 animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
            {/* Header */}
            <div className="flex items-center justify-between border-b border-subtle pb-3">
              <div className="flex items-center gap-2.5">
                <div className="p-2.5 rounded-xl bg-purple-500/10 text-purple-400 border border-purple-500/20">
                  <Train size={20} />
                </div>
                <div>
                  <h3 className="font-extrabold text-base text-main">AI Train &amp; Route Guide Generator</h3>
                  <p className="text-xs text-muted">Generate full SEO-ready article, timetable table, FAQs, and internal links</p>
                </div>
              </div>
              <button
                onClick={() => setShowGuideModal(false)}
                className="text-muted hover:text-main text-lg font-bold p-1 rounded-lg"
              >
                ✕
              </button>
            </div>

            {/* Inputs Form */}
            {!generatedResult ? (
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-main mb-1.5 flex items-center justify-between">
                    <span>Indian Railways Train Number (5 Digits — Optional if keywords provided)</span>
                    <span className="text-[10px] text-purple-400 font-mono">e.g. 22221</span>
                  </label>
                  <input
                    type="text"
                    maxLength={5}
                    value={trainGuideNumber}
                    onChange={(e) => setTrainGuideNumber(e.target.value.replace(/\D/g, ""))}
                    placeholder="e.g. 22221, 13128, 12002 (Optional)"
                    className="w-full px-4 py-2.5 text-base font-mono font-bold tracking-wider bg-input border border-subtle rounded-xl text-main placeholder:text-muted/50 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500"
                  />
                  <p className="text-[11px] text-muted mt-1">
                    Tip: Enter any active Express, Superfast, Garib Rath, or Vande Bharat number.
                  </p>
                </div>

                {/* Custom Keywords & Topics (Live Search Grounded) */}
                <div>
                  <label className="block text-xs font-bold text-main mb-1.5 flex items-center justify-between">
                    <span>Custom Keywords / Topics (Combine with Train or standalone)</span>
                    <span className="text-[10px] text-emerald-400 font-bold flex items-center gap-1">
                      <span>🌐 Live Search Grounded</span>
                    </span>
                  </label>
                  <input
                    type="text"
                    value={trainGuideKeywords}
                    onChange={(e) => setTrainGuideKeywords(e.target.value)}
                    placeholder="e.g. cancellation refund rules, flight vs train comparison, tatkal booking, food pantry"
                    className="w-full px-3.5 py-2.5 text-xs bg-input border border-subtle rounded-xl text-main placeholder:text-muted/50 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500"
                  />
                  <p className="text-[11px] text-muted mt-1">
                    Enter keywords to research. The engine searches Google News &amp; Wikipedia and fuses them into high-ranking headings and tables.
                  </p>
                </div>

                {/* Real-Time Web Grounding Toggle */}
                <div className="flex items-center justify-between p-3 rounded-xl bg-purple-500/5 border border-purple-500/20">
                  <div>
                    <span className="text-xs font-bold text-main block flex items-center gap-1.5">
                      <span>🌐 Live Web Grounding (Google News &amp; Wikipedia)</span>
                      <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">Active</span>
                    </span>
                    <span className="text-[11px] text-muted">
                      Extracts real-time headlines, official circulars, and encyclopedia records to eliminate AI hallucinations.
                    </span>
                  </div>
                  <input
                    type="checkbox"
                    checked={trainGuideEnableWebSearch}
                    onChange={(e) => setTrainGuideEnableWebSearch(e.target.checked)}
                    className="w-4 h-4 accent-purple-600 rounded cursor-pointer"
                  />
                </div>

                {/* Language Selection */}
                <div>
                  <label className="block text-xs font-bold text-main mb-1.5">
                    Target Publication Language
                  </label>
                  <div className="grid grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => setTrainGuideLang("en")}
                      className={`px-3 py-2.5 rounded-xl text-xs font-bold border flex items-center justify-center gap-2 transition ${
                        trainGuideLang === "en"
                          ? "bg-purple-600 text-white border-purple-500 shadow-sm"
                          : "bg-input hover:bg-card border-subtle text-muted hover:text-main"
                      }`}
                    >
                      <Globe size={14} />
                      <span>English (Global SEO)</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => setTrainGuideLang("hi")}
                      className={`px-3 py-2.5 rounded-xl text-xs font-bold border flex items-center justify-center gap-2 transition ${
                        trainGuideLang === "hi"
                          ? "bg-purple-600 text-white border-purple-500 shadow-sm"
                          : "bg-input hover:bg-card border-subtle text-muted hover:text-main"
                      }`}
                    >
                      <span>🇮🇳 हिंदी (Hindi SEO)</span>
                    </button>
                  </div>
                </div>

                {/* Multi-Select Topic Header & Content Scope */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <label className="block text-xs font-bold text-main">
                      Article Scope &amp; Editorial Topics
                    </label>
                    <span className="text-[11px] font-bold text-purple-400">
                      {trainGuideTopics.length === GUIDE_TOPIC_OPTIONS.length
                        ? `🌟 All ${GUIDE_TOPIC_OPTIONS.length} Topics (360° Mega-Guide)`
                        : `${trainGuideTopics.length} of ${GUIDE_TOPIC_OPTIONS.length} Selected`}
                    </span>
                  </div>

                  {/* Preset quick action buttons */}
                  <div className="flex flex-wrap items-center gap-1.5 pb-1">
                    <button
                      type="button"
                      onClick={selectAllTopics}
                      className={`px-2.5 py-1 text-[11px] rounded-lg font-bold border transition ${
                        trainGuideTopics.length === GUIDE_TOPIC_OPTIONS.length
                          ? "bg-purple-600/20 text-purple-300 border-purple-500/50 shadow-sm"
                          : "bg-input/60 hover:bg-input text-muted hover:text-main border-subtle"
                      }`}
                    >
                      🌟 Select All (360° Complete Guide)
                    </button>
                    <button
                      type="button"
                      onClick={() => selectSingleTopic("cancellation_refund")}
                      className={`px-2.5 py-1 text-[11px] rounded-lg font-bold border transition ${
                        trainGuideTopics.length === 1 && trainGuideTopics[0] === "cancellation_refund"
                          ? "bg-purple-600/20 text-purple-300 border-purple-500/50 shadow-sm"
                          : "bg-input/60 hover:bg-input text-muted hover:text-main border-subtle"
                      }`}
                    >
                      📉 Cancellation &amp; Refund
                    </button>
                    <button
                      type="button"
                      onClick={() => selectSingleTopic("flight_vs_train")}
                      className={`px-2.5 py-1 text-[11px] rounded-lg font-bold border transition ${
                        trainGuideTopics.length === 1 && trainGuideTopics[0] === "flight_vs_train"
                          ? "bg-purple-600/20 text-purple-300 border-purple-500/50 shadow-sm"
                          : "bg-input/60 hover:bg-input text-muted hover:text-main border-subtle"
                      }`}
                    >
                      ✈️ Flight vs Train
                    </button>
                    <button
                      type="button"
                      onClick={() => selectSingleTopic("history")}
                      className={`px-2.5 py-1 text-[11px] rounded-lg font-bold border transition ${
                        trainGuideTopics.length === 1 && trainGuideTopics[0] === "history"
                          ? "bg-purple-600/20 text-purple-300 border-purple-500/50 shadow-sm"
                          : "bg-input/60 hover:bg-input text-muted hover:text-main border-subtle"
                      }`}
                    >
                      📜 History Only
                    </button>
                    <button
                      type="button"
                      onClick={() => selectSingleTopic("timetable")}
                      className={`px-2.5 py-1 text-[11px] rounded-lg font-bold border transition ${
                        trainGuideTopics.length === 1 && trainGuideTopics[0] === "timetable"
                          ? "bg-purple-600/20 text-purple-300 border-purple-500/50 shadow-sm"
                          : "bg-input/60 hover:bg-input text-muted hover:text-main border-subtle"
                      }`}
                    >
                      🕒 Timetable Only
                    </button>
                    <button
                      type="button"
                      onClick={() => selectSingleTopic("food_pantry")}
                      className={`px-2.5 py-1 text-[11px] rounded-lg font-bold border transition ${
                        trainGuideTopics.length === 1 && trainGuideTopics[0] === "food_pantry"
                          ? "bg-purple-600/20 text-purple-300 border-purple-500/50 shadow-sm"
                          : "bg-input/60 hover:bg-input text-muted hover:text-main border-subtle"
                      }`}
                    >
                      🍽️ Food &amp; Delicacies Only
                    </button>
                  </div>

                  {/* Multi-Select Cards Grid */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-56 overflow-y-auto pr-1">
                    {GUIDE_TOPIC_OPTIONS.map((topic) => {
                      const isSelected = trainGuideTopics.includes(topic.id);
                      return (
                        <button
                          key={topic.id}
                          type="button"
                          onClick={() => toggleTopic(topic.id)}
                          className={`flex items-start gap-2.5 p-2.5 rounded-xl border text-left transition ${
                            isSelected
                              ? "bg-purple-500/10 border-purple-500/40 text-main shadow-sm ring-1 ring-purple-500/30"
                              : "bg-input/40 hover:bg-input/80 border-subtle text-muted"
                          }`}
                        >
                          <div className={`mt-0.5 w-4 h-4 rounded flex items-center justify-center shrink-0 border transition ${
                            isSelected
                              ? "bg-purple-600 border-purple-500 text-white"
                              : "border-subtle bg-card"
                          }`}>
                            {isSelected && <span className="text-[10px] font-black leading-none">✓</span>}
                          </div>
                          <div className="min-w-0 flex-1">
                            <span className="text-xs font-bold block truncate text-main">
                              {topic.icon} {trainGuideLang === "hi" ? topic.labelHi : topic.labelEn}
                            </span>
                            <span className="text-[10px] text-muted block line-clamp-1 leading-tight mt-0.5">
                              {trainGuideLang === "hi" ? topic.descHi : topic.descEn}
                            </span>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>

                {/* Auto-publish toggle */}
                <div className="flex items-center justify-between p-3 rounded-xl bg-input/50 border border-subtle">
                  <div>
                    <span className="text-xs font-bold text-main block">Auto-Publish Immediately</span>
                    <span className="text-[11px] text-muted">Make article live on /news immediately upon generation</span>
                  </div>
                  <input
                    type="checkbox"
                    checked={trainGuideAutoPublish}
                    onChange={(e) => setTrainGuideAutoPublish(e.target.checked)}
                    className="w-4 h-4 accent-purple-600 rounded cursor-pointer"
                  />
                </div>

                {/* Actions */}
                <div className="flex items-center justify-end gap-3 pt-2">
                  <button
                    type="button"
                    onClick={() => setShowGuideModal(false)}
                    disabled={generatingGuide}
                    className="px-4 py-2 text-xs font-bold bg-input hover:bg-card border border-subtle text-main rounded-xl transition"
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={handleGenerateTrainGuide}
                    disabled={generatingGuide || (!trainGuideNumber.trim() && !trainGuideKeywords.trim())}
                    className="flex items-center gap-2 px-5 py-2.5 text-xs font-bold bg-purple-600 hover:bg-purple-700 text-white rounded-xl shadow-md transition disabled:opacity-50"
                  >
                    {generatingGuide ? (
                      <>
                        <Loader2 size={13} className="animate-spin" />
                        <span>Generating Full Guide with AI...</span>
                      </>
                    ) : (
                      <>
                        <Sparkles size={13} />
                        <span>Generate Article Now</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            ) : (
              /* Success / Result Screen */
              <div className="space-y-4">
                <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 space-y-1">
                  <div className="flex items-center gap-2 font-bold text-sm">
                    <CheckCircle2 size={16} />
                    <span>Train Guide Created Successfully!</span>
                  </div>
                  <p className="text-xs text-muted">
                    Article has been saved to your CMS with full timetable, FAQs, and internal links.
                  </p>
                </div>

                <div className="p-4 bg-input/50 border border-subtle rounded-xl space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-main">{generatedResult.title}</span>
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      generatedResult.status === "PUBLISHED"
                        ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                        : "bg-indigo-500/10 text-indigo-400 border border-indigo-500/20"
                    }`}>
                      {generatedResult.status}
                    </span>
                  </div>
                  <p className="text-xs text-muted">
                    Slug: <code className="text-purple-400 font-mono">/news/{generatedResult.slug}</code>
                  </p>
                </div>

                <div className="flex items-center justify-between pt-2">
                  <button
                    onClick={() => {
                      setGeneratedResult(null);
                      setTrainGuideNumber("");
                    }}
                    className="text-xs font-bold text-purple-400 hover:underline"
                  >
                    + Generate Another Train Guide
                  </button>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setShowGuideModal(false)}
                      className="px-4 py-2 text-xs font-bold bg-input hover:bg-card border border-subtle text-main rounded-xl transition"
                    >
                      Close
                    </button>
                    {generatedResult.slug && (
                      <Link
                        href={`/news/${generatedResult.slug}`}
                        target="_blank"
                        className="flex items-center gap-1.5 px-4 py-2 text-xs font-bold bg-purple-600 hover:bg-purple-700 text-white rounded-xl shadow-md transition"
                      >
                        <span>View Live Article</span>
                        <ExternalLink size={12} />
                      </Link>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
