"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  Smartphone,
  ShieldCheck,
  ShieldAlert,
  Users,
  CheckCircle2,
  Clock,
  AlertTriangle,
  RefreshCw,
  TrendingUp,
  Percent,
  HelpCircle,
  Calendar,
  Lock,
  ArrowRight,
  Database
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

export interface MobileVerificationSummary {
  totalUsers: number;
  verifiedMobileUsers: number;
  unverifiedMobileUsers: number;
  enteredNotVerifiedUsers: number;
  noMobileEnteredUsers: number;
  verificationPercentage: number;
  otpRequestsToday: number | null;
  successfulVerificationsToday: number;
  failedOrExpiredAttempts: number | null;
}

export interface VerificationDailyTrendPoint {
  date: string;
  label: string;
  verifications: number;
  signups: number;
}

export interface VerificationRolloutPolicyStatus {
  gracePeriodDays: number;
  launchDate: string;
  enforcementDeadline: string;
  isGateActive: boolean;
}

export interface VerificationDataIntegrity {
  authoritativeSource: string;
  authOtpsAccessRestricted: boolean;
  notes: string[];
  lastUpdated: string;
}

export interface MobileVerificationAnalyticsResponse {
  summary: MobileVerificationSummary;
  rolloutPolicy: VerificationRolloutPolicyStatus;
  dailyTrend: VerificationDailyTrendPoint[];
  dataIntegrity: VerificationDataIntegrity;
}

export interface MobileVerificationPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast?: (msg: string, type: "success" | "error" | "info") => void;
}

export function MobileVerificationPanel({ api, getAuthHeaders, triggerToast }: MobileVerificationPanelProps) {
  const [data, setData] = useState<MobileVerificationAnalyticsResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchAnalytics = useCallback(async (isManualRefresh = false) => {
    if (isManualRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      const res = await fetchWithAuth(`${api}/api/admin/mobile-verification/analytics`, {
        headers: getAuthHeaders()
      });

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }

      const json = await res.json();
      if (!json.success || !json.data) {
        throw new Error(json.error || "Failed to load mobile verification analytics");
      }

      setData(json.data);
      if (isManualRefresh && triggerToast) {
        triggerToast("Mobile verification metrics refreshed successfully", "success");
      }
    } catch (err: any) {
      setError(err.message || "Failed to retrieve analytics");
      if (isManualRefresh && triggerToast) {
        triggerToast(err.message || "Refresh failed", "error");
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchAnalytics();
  }, [fetchAnalytics]);

  if (loading && !data) {
    return (
      <div className="bg-card p-10 rounded-2xl border border-subtle shadow-sm flex flex-col items-center justify-center min-h-[360px] space-y-4">
        <RefreshCw size={28} className="animate-spin text-primary" />
        <p className="text-xs text-muted font-medium">Aggregating authoritative mobile verification records...</p>
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="bg-card p-8 rounded-2xl border border-danger/30 shadow-sm flex flex-col items-center text-center space-y-4">
        <ShieldAlert size={36} className="text-danger" />
        <div>
          <h3 className="text-base font-bold text-main">Failed to Load Verification Analytics</h3>
          <p className="text-xs text-muted mt-1 max-w-md">{error}</p>
        </div>
        <button
          onClick={() => fetchAnalytics(true)}
          className="px-4 py-2 bg-input hover:bg-card border border-subtle rounded-lg text-xs font-bold text-main transition flex items-center gap-2"
        >
          <RefreshCw size={13} /> Retry Query
        </button>
      </div>
    );
  }

  const summary = data?.summary;
  const rollout = data?.rolloutPolicy;
  const dailyTrend = data?.dailyTrend || [];
  const integrity = data?.dataIntegrity;

  const totalUsers = summary?.totalUsers || 0;
  const verifiedUsers = summary?.verifiedMobileUsers || 0;
  const unverifiedUsers = summary?.unverifiedMobileUsers || 0;
  const enteredNotVerified = summary?.enteredNotVerifiedUsers || 0;
  const noMobile = summary?.noMobileEnteredUsers || 0;
  const percent = summary?.verificationPercentage || 0;

  const formattedLastUpdated = integrity?.lastUpdated
    ? new Date(integrity.lastUpdated).toLocaleTimeString("en-US", {
        timeZone: "Asia/Kolkata",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hour12: true
      }) + " IST"
    : "Just now";

  // Calculate highest daily value for bar scaling
  const maxTrendVal = Math.max(
    ...dailyTrend.map(d => Math.max(d.verifications, d.signups)),
    5
  );

  return (
    <div className="space-y-6">
      {/* Panel Header */}
      <div className="bg-card p-6 md:p-8 rounded-2xl border border-subtle shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-start gap-4">
          <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-xl text-emerald-400 mt-0.5">
            <Smartphone size={24} />
          </div>
          <div>
            <div className="flex items-center gap-2.5">
              <h2 className="text-xl font-bold tracking-tight text-main">Mobile Verification Intelligence</h2>
              <span className="px-2.5 py-0.5 text-[10px] font-black uppercase tracking-wider rounded-full bg-emerald-500/10 border border-emerald-500/25 text-emerald-400">
                Live Rollout
              </span>
            </div>
            <p className="text-xs text-muted mt-1 leading-relaxed">
              Authoritative passenger phone adoption, verification telemetry, and 14-day policy rollout monitoring.
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <div className="text-[10px] text-muted font-mono uppercase tracking-wider">Last Computed</div>
            <div className="text-xs font-bold text-main font-mono">{formattedLastUpdated}</div>
          </div>
          <button
            onClick={() => fetchAnalytics(true)}
            disabled={refreshing}
            className="px-3.5 py-2 bg-input hover:bg-card border border-subtle rounded-xl text-xs font-bold text-main transition flex items-center gap-2 shadow-sm disabled:opacity-50"
          >
            <RefreshCw size={13} className={refreshing ? "animate-spin text-primary" : "text-muted"} />
            <span>{refreshing ? "Refreshing..." : "Refresh"}</span>
          </button>
        </div>
      </div>

      {/* Rollout Policy & Search Gating Status Banner */}
      <div className="bg-gradient-to-r from-indigo-500/10 via-purple-500/10 to-emerald-500/10 border border-indigo-500/20 rounded-2xl p-5 backdrop-blur-sm">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-indigo-500/20 rounded-lg text-indigo-400">
              <Calendar size={18} />
            </div>
            <div>
              <div className="text-xs font-bold text-main flex items-center gap-2">
                <span>14-Day Progressive Rollout Policy</span>
                <span className="text-[10px] text-muted font-normal">({rollout?.gracePeriodDays || 14} Days Grace Period)</span>
              </div>
              <div className="text-[11px] text-muted mt-0.5">
                Mandatory Search Gating activates after: <strong className="text-main font-mono">{rollout?.enforcementDeadline ? new Date(rollout.enforcementDeadline).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "Nov 8, 2026"}</strong>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4 text-xs font-mono">
            <div className="px-3 py-1.5 rounded-lg bg-input border border-subtle flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
              <span className="text-muted text-[10px]">Kill-Switch:</span>
              <span className="font-bold text-main">{rollout?.isGateActive ? "ARMED (Default)" : "BYPASS (Kill-Switch Active)"}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Key Metric Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Total Users */}
        <div className="bg-card p-5 rounded-2xl border border-subtle shadow-sm hover:border-primary/40 transition">
          <div className="flex items-center justify-between text-muted">
            <span className="text-xs font-bold uppercase tracking-wider">Total Registered</span>
            <Users size={16} className="text-indigo-400" />
          </div>
          <div className="text-3xl font-black text-main mt-3 tracking-tight font-mono">
            {totalUsers.toLocaleString()}
          </div>
          <div className="text-[10px] text-muted mt-1.5 flex items-center gap-1.5 font-medium">
            <Database size={11} className="text-muted" />
            <span>Authoritative user registry</span>
          </div>
        </div>

        {/* Verified Mobile Users */}
        <div className="bg-card p-5 rounded-2xl border border-emerald-500/30 shadow-sm hover:border-emerald-500/60 transition bg-emerald-500/[0.02]">
          <div className="flex items-center justify-between text-muted">
            <span className="text-xs font-bold uppercase tracking-wider text-emerald-400">Verified Mobile</span>
            <ShieldCheck size={16} className="text-emerald-400" />
          </div>
          <div className="text-3xl font-black text-emerald-400 mt-3 tracking-tight font-mono">
            {verifiedUsers.toLocaleString()}
          </div>
          <div className="text-[10px] text-emerald-500/80 mt-1.5 flex items-center gap-1.5 font-bold">
            <CheckCircle2 size={11} />
            <span>{percent}% adoption completion</span>
          </div>
        </div>

        {/* Entered but Not Verified */}
        <div className="bg-card p-5 rounded-2xl border border-amber-500/30 shadow-sm hover:border-amber-500/60 transition bg-amber-500/[0.02]">
          <div className="flex items-center justify-between text-muted">
            <span className="text-xs font-bold uppercase tracking-wider text-amber-400">Entered (Pending OTP)</span>
            <Clock size={16} className="text-amber-400" />
          </div>
          <div className="text-3xl font-black text-amber-400 mt-3 tracking-tight font-mono">
            {enteredNotVerified.toLocaleString()}
          </div>
          <div className="text-[10px] text-amber-500/80 mt-1.5 flex items-center gap-1.5 font-medium">
            <AlertTriangle size={11} />
            <span>Target cohort for in-app reminders</span>
          </div>
        </div>

        {/* No Mobile Number Entered */}
        <div className="bg-card p-5 rounded-2xl border border-subtle shadow-sm hover:border-primary/40 transition">
          <div className="flex items-center justify-between text-muted">
            <span className="text-xs font-bold uppercase tracking-wider">No Mobile Entered</span>
            <Smartphone size={16} className="text-rose-400" />
          </div>
          <div className="text-3xl font-black text-main mt-3 tracking-tight font-mono">
            {noMobile.toLocaleString()}
          </div>
          <div className="text-[10px] text-muted mt-1.5 flex items-center gap-1.5 font-medium">
            <span>Email-only passenger accounts</span>
          </div>
        </div>
      </div>

      {/* Progress & Adoption Funnel Visual */}
      <div className="bg-card p-6 md:p-8 rounded-2xl border border-subtle shadow-sm space-y-6">
        <div>
          <div className="flex justify-between items-center mb-2">
            <div className="text-xs font-bold text-main uppercase tracking-wider flex items-center gap-2">
              <Percent size={14} className="text-emerald-400" />
              <span>Platform Verification Progress</span>
            </div>
            <span className="text-xs font-mono font-bold text-emerald-400">{percent}% Verified</span>
          </div>

          <div className="w-full bg-input h-3 rounded-full overflow-hidden flex border border-subtle">
            <div
              className="bg-emerald-500 h-full transition-all duration-500 ease-out"
              style={{ width: `${Math.max(percent, 0.5)}%` }}
              title={`Verified: ${verifiedUsers} users (${percent}%)`}
            />
            <div
              className="bg-amber-500 h-full transition-all duration-500 ease-out"
              style={{ width: `${totalUsers > 0 ? (enteredNotVerified / totalUsers) * 100 : 0}%` }}
              title={`Entered but pending: ${enteredNotVerified} users`}
            />
          </div>

          <div className="flex flex-wrap items-center gap-6 mt-3 text-xs text-muted">
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 rounded-full bg-emerald-500" />
              <span>Verified Mobile: <strong className="text-main">{verifiedUsers}</strong></span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 rounded-full bg-amber-500" />
              <span>Phone Entered Pending OTP: <strong className="text-main">{enteredNotVerified}</strong></span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 rounded-full bg-input border border-subtle" />
              <span>No Mobile Number: <strong className="text-main">{noMobile}</strong></span>
            </div>
          </div>
        </div>

        {/* Today's Activity & Velocity */}
        <div className="border-t border-subtle pt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-input p-4 rounded-xl border border-subtle">
            <div className="text-[11px] text-muted font-bold uppercase tracking-wider">Verifications Today</div>
            <div className="text-2xl font-black text-emerald-400 mt-2 font-mono">
              {summary?.successfulVerificationsToday ?? 0}
            </div>
            <div className="text-[10px] text-muted mt-1">Confirmed OTP verifications logged today</div>
          </div>

          <div className="bg-input p-4 rounded-xl border border-subtle">
            <div className="text-[11px] text-muted font-bold uppercase tracking-wider flex items-center justify-between">
              <span>OTP Requests Today</span>
              {integrity?.authOtpsAccessRestricted && (
                <span className="text-[9px] text-amber-400 font-normal">RLS Protected</span>
              )}
            </div>
            <div className="text-2xl font-black text-main mt-2 font-mono">
              {summary?.otpRequestsToday !== null ? summary?.otpRequestsToday : "—"}
            </div>
            <div className="text-[10px] text-muted mt-1">
              {summary?.otpRequestsToday !== null ? "Total dispatch requests dispatched today" : "Requires service_role direct table access"}
            </div>
          </div>

          <div className="bg-input p-4 rounded-xl border border-subtle">
            <div className="text-[11px] text-muted font-bold uppercase tracking-wider">Failed / Expired Attempts</div>
            <div className="text-2xl font-black text-main mt-2 font-mono">
              {summary?.failedOrExpiredAttempts !== null ? summary?.failedOrExpiredAttempts : "—"}
            </div>
            <div className="text-[10px] text-muted mt-1">
              {summary?.failedOrExpiredAttempts !== null ? "Burned or expired attempts recorded" : "Isolated under principle of least privilege"}
            </div>
          </div>
        </div>
      </div>

      {/* 7-Day Activity Trend */}
      <div className="bg-card p-6 md:p-8 rounded-2xl border border-subtle shadow-sm">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h3 className="text-sm font-bold uppercase tracking-wider text-main flex items-center gap-2">
              <TrendingUp size={16} className="text-primary" />
              <span>7-Day Verification &amp; Registration Velocity</span>
            </h3>
            <p className="text-xs text-muted mt-0.5">Daily comparisons of new user signups vs confirmed mobile verifications</p>
          </div>
          <div className="flex items-center gap-4 text-[10px] text-muted font-mono">
            <div className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-sm bg-primary" />
              <span>New Signups</span>
            </div>
            <div className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-sm bg-emerald-400" />
              <span>Verifications</span>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-7 gap-2 md:gap-4 pt-4 border-t border-subtle">
          {dailyTrend.map((point, idx) => {
            const signupHeight = Math.max(12, Math.round((point.signups / maxTrendVal) * 110));
            const verifyHeight = Math.max(8, Math.round((point.verifications / maxTrendVal) * 110));

            return (
              <div key={point.date || idx} className="flex flex-col items-center gap-2">
                <div className="h-[120px] w-full flex items-end justify-center gap-1.5 bg-input/40 rounded-lg p-1.5 border border-subtle/50">
                  {/* Signup Bar */}
                  <div
                    className="w-1/2 bg-primary/70 hover:bg-primary rounded-t transition-all duration-300 relative group cursor-pointer"
                    style={{ height: `${signupHeight}px` }}
                  >
                    <div className="absolute -top-7 left-1/2 -translate-x-1/2 bg-card border border-subtle px-1.5 py-0.5 rounded text-[9px] font-mono font-bold text-main opacity-0 group-hover:opacity-100 transition shadow pointer-events-none z-10 whitespace-nowrap">
                      {point.signups} signups
                    </div>
                  </div>

                  {/* Verification Bar */}
                  <div
                    className="w-1/2 bg-emerald-400/80 hover:bg-emerald-400 rounded-t transition-all duration-300 relative group cursor-pointer"
                    style={{ height: `${verifyHeight}px` }}
                  >
                    <div className="absolute -top-7 left-1/2 -translate-x-1/2 bg-card border border-subtle px-1.5 py-0.5 rounded text-[9px] font-mono font-bold text-emerald-400 opacity-0 group-hover:opacity-100 transition shadow pointer-events-none z-10 whitespace-nowrap">
                      {point.verifications} verified
                    </div>
                  </div>
                </div>

                <div className="text-[10px] font-mono text-muted text-center truncate max-w-full">
                  {point.label.split(',')[0]}
                </div>
                <div className="text-[9px] font-mono font-bold text-main">
                  {point.verifications}v / {point.signups}s
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Security & Data Integrity Notes */}
      <div className="bg-surface p-5 rounded-2xl border border-subtle text-xs space-y-2">
        <div className="flex items-center gap-2 font-bold text-main">
          <Lock size={14} className="text-indigo-400" />
          <span>Security &amp; Data Integrity Guarantees</span>
        </div>
        <ul className="list-disc pl-5 space-y-1 text-muted text-[11px] leading-relaxed">
          {integrity?.notes.map((note, index) => (
            <li key={index}>{note}</li>
          ))}
          <li>
            Zero PII exposure: Phone numbers, OTP plaintext codes, cryptographic hashes, and provider tokens are excluded from all admin responses.
          </li>
          <li>
            Factor isolation: Mobile verification is stored strictly under <code className="text-secondary bg-input px-1 py-0.5 rounded font-mono">mobile_verified</code> and does not conflate with email authentication.
          </li>
        </ul>
      </div>
    </div>
  );
}
